{"implementation":"def solve(case):
    refinement = case["refinement"]
    edges = case["edges"]
    group_to_vertices = {}
    for vertex, group in refinement.items():
        group_to_vertices.setdefault(group, []).append(vertex)
    from collections import defaultdict
    group_weights = defaultdict(int)
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        if gu != gv:
            key = tuple(sorted((gu, gv)))
            group_weights[key] += w
    aggregate_edges = [[g1, g2, w] for (g1, g2), w in group_weights.items()]
    return {"aggregate_edges": aggregate_edges, "members": group_to_vertices}"}
